"use client";

import Link from "next/link";
import { useEffect, useRef } from "react";
import { gsap } from "gsap";

export default function HeroSection() {
    const rootRef = useRef<HTMLElement>(null);

    useEffect(() => {
        const ctx = gsap.context(() => {
            const tl = gsap.timeline({ defaults: { ease: "power4.out" } });

            tl.set(".hero-reveal", { clipPath: "inset(0 0 100% 0)" })
                .set(".hero-fade", { opacity: 0, y: 24 })
                .to(".hero-kicker", { opacity: 1, x: 0, duration: 1, delay: 0.2 })
                .to(".hero-reveal", { clipPath: "inset(0 0 0% 0)", duration: 1.4, stagger: 0.12 }, "-=0.7")
                .to(".hero-fade", { opacity: 1, y: 0, duration: 1, stagger: 0.08 }, "-=0.9")
                .fromTo(".hero-image", { scale: 1.15 }, { scale: 1, duration: 2.2, ease: "power2.out" }, 0);
        }, rootRef);

        return () => ctx.revert();
    }, []);

    // Magnetic pull for CTAs — hook this into a shared cursor context later if you add one
    const magnetize = (e: React.MouseEvent<HTMLElement>) => {
        const el = e.currentTarget;
        const { left, top, width, height } = el.getBoundingClientRect();
        const x = e.clientX - (left + width / 2);
        const y = e.clientY - (top + height / 2);
        gsap.to(el, { x: x * 0.3, y: y * 0.3, duration: 0.4, ease: "power2.out" });
    };
    const resetMagnet = (e: React.MouseEvent<HTMLElement>) => {
        gsap.to(e.currentTarget, { x: 0, y: 0, duration: 0.5, ease: "elastic.out(1, 0.4)" });
    };

    return (
        <section ref={rootRef} id="hero" className="relative w-full h-[110vh] overflow-hidden bg-black">
            <img
                src="/images/hero-section.png"
                alt="High-rise HVAC and elevator installation"
                className="hero-image absolute inset-0 w-full h-full object-cover"
            />

            <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/20 to-black/40" />
            <div className="absolute inset-0 bg-gradient-to-r from-black/60 via-transparent to-transparent" />

            {/* Rotated kicker, pinned to the left edge — asymmetrical anchor point */}
            <div className="hero-kicker absolute left-6 lg:left-10 top-1/2 -translate-y-1/2 opacity-0 -translate-x-4 origin-left -rotate-90 hidden md:block">
                <span className="font-label-caps text-label-caps text-secondary-fixed uppercase tracking-[0.35em] whitespace-nowrap">
                    Est. Dubai — Turnkey Vertical Mobility
                </span>
            </div>

            <div className="relative h-full max-w-[1440px] mx-auto px-margin grid grid-cols-12 gap-x-6">

                {/* Headline block — offset left, sits high rather than bottom-anchored */}
                <div className="col-span-12 lg:col-span-8 flex flex-col justify-center h-full pt-[8vh]">
                    <span className="hero-fade font-label-caps text-label-caps text-secondary-fixed uppercase tracking-[0.2em] mb-space-md md:hidden [text-shadow:0_1px_12px_rgba(0,0,0,0.6)]">
                        Turnkey HVAC &amp; Vertical Mobility
                    </span>

                    <h1 className="text-on-primary tracking-tight leading-[0.95] max-w-[920px]">
                        <span className="hero-reveal block font-display-hero text-display-hero [text-shadow:0_2px_24px_rgba(0,0,0,0.5)]">
                            Precision engineering
                        </span>
                        <span className="hero-reveal block font-display-hero text-display-hero [text-shadow:0_2px_24px_rgba(0,0,0,0.5)]">
                            for <em className="font-serif-display not-italic italic text-secondary-fixed">high-rise</em>
                        </span>
                        <span className="hero-reveal block font-display-hero text-display-hero [text-shadow:0_2px_24px_rgba(0,0,0,0.5)]">
                            structures
                        </span>
                    </h1>

                    <div className="hero-fade flex flex-wrap items-center gap-space-md mt-space-2xl">
                        <Link
                            onMouseMove={magnetize}
                            onMouseLeave={resetMagnet}
                            className="inline-flex items-center justify-center px-space-lg py-space-md bg-secondary hover:bg-secondary-container text-on-secondary font-label-md text-label-md rounded transition-colors"
                            href="/services"
                        >
                            Explore Services
                            <span className="material-symbols-outlined text-[18px] ml-space-xs">arrow_forward</span>
                        </Link>

                        
                        <a  onMouseMove={magnetize}
                            onMouseLeave={resetMagnet}
                            className="inline-flex items-center justify-center px-space-lg py-space-md text-on-primary font-label-md text-label-md rounded border border-on-primary/40 hover:border-on-primary transition-colors"
                            href="https://wa.me/97142888490"
                            rel="noopener noreferrer"
                            target="_blank"
                        >
                            <span className="material-symbols-outlined text-[18px] mr-space-xs">bolt</span>
                            WhatsApp Dispatch
                        </a>
                    </div>
                </div>

                {/* Right meta column — balances the asymmetry, editorial "spec sheet" feel */}
                <div className="hero-fade hidden lg:flex col-span-4 flex-col justify-end items-end text-right pb-32 gap-space-lg">
                    <div className="flex flex-col items-end">
                        <span className="font-display-hero text-[2.5rem] text-on-primary leading-none">15+</span>
                        <span className="font-label-caps text-label-caps text-on-primary/60 uppercase tracking-[0.15em] mt-1">Years in the field</span>
                    </div>
                    <div className="w-16 h-px bg-on-primary/30" />
                    <div className="flex flex-col items-end">
                        <span className="font-display-hero text-[2.5rem] text-on-primary leading-none">UAE</span>
                        <span className="font-label-caps text-label-caps text-on-primary/60 uppercase tracking-[0.15em] mt-1">Dubai-wide dispatch</span>
                    </div>
                </div>
            </div>

            {/* Scroll cue, bottom-right */}
            <div className="hero-fade absolute bottom-10 right-6 lg:right-10 flex items-center gap-space-sm">
                <span className="font-label-caps text-label-caps text-on-primary/70 uppercase tracking-[0.2em]">Scroll</span>
                <span className="block w-px h-10 bg-on-primary/40 relative overflow-hidden">
                    <span className="absolute inset-x-0 top-0 h-1/2 bg-secondary-fixed animate-[scrollcue_1.8s_ease-in-out_infinite]" />
                </span>
            </div>

            <style jsx>{`
                @keyframes scrollcue {
                    0% { transform: translateY(-100%); }
                    100% { transform: translateY(200%); }
                }
            `}</style>
        </section>
    );
}